tool_calls.arguments_json:
{"function":"() => {
  const pricePerOrderInputs = Array.from(document.querySelectorAll('input[name="pricePerOrder"]'));
  const unitPriceInputs = Array.from(document.querySelectorAll('input[name="unitPrice"]'));
  const unitMeasureSelects = Array.from(document.querySelectorAll('select[name="unitMeasure"]'));

  // Let's modify rows 0, 1, 2 (Standard shipping)
  for (let i = 0; i < 3; i++) {
    const ppo = pricePerOrderInputs[i];
    const up = unitPriceInputs[i];
    const um = unitMeasureSelects[i];

    if (ppo) {
      ppo.focus();
      ppo.value = "0.00";
      ppo.dispatchEvent(new Event('input', { bubbles: true }));
      ppo.dispatchEvent(new Event('change', { bubbles: true }));
      ppo.blur();
    }

    if (up) {
      up.focus();
      up.value = "8.99";
      up.dispatchEvent(new Event('input', { bubbles: true }));
      up.dispatchEvent(new Event('change', { bubbles: true }));
      up.blur();
    }

    if (um) {
      um.value = "Per Item";
      um.dispatchEvent(new Event('change', { bubbles: true }));
      // Also update AUI prompt if present
      const prompt = um.parentElement ? um.parentElement.querySelector('.a-dropdown-prompt') : null;
      if (prompt) prompt.innerText = "商品";
    }
  }

  return {
    row0: { ppo: pricePerOrderInputs[0].value, up: unitPriceInputs[0].value, um: unitMeasureSelects[0].value },
    row1: { ppo: pricePerOrderInputs[1].value, up: unitPriceInputs[1].value, um: unitMeasureSelects[1].value },
    row2: { ppo: pricePerOrderInputs[2].value, up: unitPriceInputs[2].value, um: unitMeasureSelects[2].value }
  };
}","pageId":1,"toolSummary":"Update Rows 0, 1, 2 to $0 order + $8.99 per item","waitForStableDom":false}

